<?php
declare(strict_types=1);
namespace BSPDesign;
require_once __DIR__.'/model.php';
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function fmt($v):string{return is_numeric($v)?sprintf('%.8g',$v):(string)$v;}
function json_pretty($v):string{return json_encode($v,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRESERVE_ZERO_FRACTION|JSON_THROW_ON_ERROR);}
function security():void{header_remove('X-Powered-By');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: strict-origin-when-cross-origin');header('Permissions-Policy: camera=(), microphone=(), geolocation=()');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-src 'none'; frame-ancestors 'none'; form-action 'self'");header('Cache-Control: no-store');}
function route(string $path,array $allowed):string{security();$p=parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH);if(!in_array($p,[$path,$path.'index.php'],true)){http_response_code(404);exit('Not found');}$method=$_SERVER['REQUEST_METHOD']??'GET';if(!in_array($method,$allowed,true)){http_response_code(405);header('Allow: '.implode(', ',$allowed));exit('Method not allowed');}return $method;}
function start(string $title,string $desc,string $path,bool $noindex=false):void{if($noindex)header('X-Robots-Tag: noindex, follow');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=h($title)?> | Beyond Spacetime</title><meta name="description" content="<?=h($desc)?>"><meta name="robots" content="<?=$noindex?'noindex, follow':'index, follow'?>"><link rel="canonical" href="<?=h(BASE.$path)?>"><meta property="og:title" content="<?=h($title)?>"><meta property="og:description" content="<?=h($desc)?>"><meta property="og:url" content="<?=h(BASE.$path)?>"><meta property="og:image" content="<?=BASE?>/foundations/assets/banner.webp"><link rel="icon" href="/foundations/assets/compass.png"><link rel="stylesheet" href="/experiment-design/assets/design.css?v=2.3.0"><script src="/experiment-design/assets/design.js?v=2.3.0" defer></script><script type="application/ld+json"><?=json_encode(['@context'=>'https://schema.org','@type'=>'WebPage','name'=>$title,'description'=>$desc,'url'=>BASE.$path,'inLanguage'=>'en'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)?></script></head><body><a class="skip" href="#main">Skip to content</a><header><div class="nav"><a class="brand" href="/museum/"><img src="/foundations/assets/compass.png" width="40" height="40" alt="">Beyond <b>Spacetime</b></a><nav aria-label="Main navigation"><a href="/museum/">Museum</a><a href="/museum/search/">Search</a><a href="/evidence/">Evidence</a><a href="/research/">Research</a><a href="/knowledge-graph/">Graph</a><a href="/experiment-design/"<?=($path===ROOT?' aria-current="page"':'')?>>Design</a></nav></div></header><main id="main"><div class="crumb"><a href="/museum/">Museum</a> / Experiment design</div><?php }
function endpage():void{?></main><footer><a href="/experiment-design/method/">Method and API</a> · <a href="/experiment-design/replay/">Replay protocol</a> · <a href="https://arcsecs.com/read-scientific-paper/">Original research ↗</a><p>Numerical education only. No new observational evidence. No account, tracking or server-side protocol storage; hosting logs may exist.</p></footer></body></html><?php }
function download(array $r,string $name):never{header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="'.$name.'"');echo json_pretty($r);exit;}
function decode_text($s):array{if(!is_string($s)||strlen($s)>65536)throw new \InvalidArgumentException('Provide JSON up to 64 KiB.');return obj(json_decode($s,true,32,JSON_THROW_ON_ERROR),'JSON');}
function form_num($v,string $k):float{if(!is_string($v)||strlen($v)>64||!is_numeric($v)||!is_finite((float)$v))throw new \InvalidArgumentException('Invalid number: '.$k);return (float)$v;}
function from_form(array $f):array{$p=obj($f['protocol']??null,'Protocol');foreach(['criteria','uncertainty'] as $group){$p[$group]=obj($p[$group]??null,$group);foreach($p[$group] as $k=>$v)$p[$group][$k]=form_num($v,$k);}$p['cases']=obj($p['cases']??null,'Cases');foreach($p['cases'] as $role=>$row){$p['cases'][$role]=obj($row,$role);foreach($row as $k=>$v)$p['cases'][$role][$k]=form_num($v,$k);}if(!is_string($p['metric']??null)||!ctype_digit($p['metric']))throw new \InvalidArgumentException('Invalid metric.');$p['metric']=(int)$p['metric'];$p['evidence']=$p['evidence']??[];$p['gates']=$p['gates']??[];return $p;}
function custom(string $id):array{$m=model_specs()[$id];$ref=array_column($m['params'],'default','key');$v=$m['params'][0];$c=$p=$ref;$c[$v['key']]=$v['min']+($v['max']-$v['min'])/3;$p[$v['key']]=$v['max'];if($c[$v['key']]===$ref[$v['key']])$c[$v['key']]=$v['min'];if($p[$v['key']]===$ref[$v['key']])$p[$v['key']]=$v['min']+2*($v['max']-$v['min'])/3;return template('Custom '.$m['title'],$id,$v['key'],$m['metrics'][0]['index'],'increase',[$ref,$c,$ref,$p],[.1,.01,.001,.1],array_fill_keys(['question','hypothesis','alternative','negative_control','positive_control','measurement_plan','confounders','stopping_rule'],''),$m['evidence'],[]);}
function input(string $name,string $label,$v,string $type='text',string $extra=''):void{?><label class="field"><span><?=h($label)?></span><input required type="<?=h($type)?>" name="<?=h($name)?>" value="<?=h($v)?>" <?=$extra?>></label><?php }
function form(array $p):void{$m=model_specs()[$p['model']];?><form action="/experiment-design/" method="post" class="editor"><input type="hidden" name="protocol[schema]" value="<?=SCHEMA?>"><input type="hidden" name="protocol[model]" value="<?=h($p['model'])?>"><section class="panel"><h2>1 · Define the question</h2><?php input('protocol[title]','Protocol title',$p['title'],'text','maxlength="160"');?> <p>Model: <a href="<?=h($m['url'])?>"><?=h($m['title'])?></a> · <a href="/knowledge-graph/record/?id=<?=h(rawurlencode('model:'.$p['model']))?>">Inspect model relationships</a></p><div class="grid two"><?php foreach(['question'=>'Research question','hypothesis'=>'Candidate hypothesis','alternative'=>'Competing explanation','measurement_plan'=>'Measurement and sampling plan','confounders'=>'Confounders and limitations','stopping_rule'=>'Stopping rule'] as $k=>$label):?><label class="field"><span><?=h($label)?></span><textarea name="protocol[notes][<?=$k?>]" required maxlength="<?=$k==='question'?600:1500?>" rows="4"><?=h($p['notes'][$k])?></textarea></label><?php endforeach;?></div><div class="grid two"><label class="field"><span>Primary independent variable</span><select name="protocol[variable]"><?php foreach($m['params'] as $v):?><option value="<?=h($v['key'])?>" <?=$v['key']===$p['variable']?'selected':''?>><?=h($v['label'])?></option><?php endforeach;?></select></label><label class="field"><span>Primary observable (numeric)</span><select name="protocol[metric]"><?php foreach($m['metrics'] as $v):?><option value="<?=$v['index']?>" <?=$v['index']===$p['metric']?'selected':''?>><?=h($v['label'].' '.$v['unit'])?></option><?php endforeach;?></select></label></div><label class="field"><span>Predicted direction of candidate effect</span><select name="protocol[direction]"><?php foreach(['increase','decrease'] as $v):?><option <?=$v===$p['direction']?'selected':''?>><?=$v?></option><?php endforeach;?></select></label></section><section class="panel"><h2>2 · Design four cases</h2><p>Candidate and positive control change only the primary variable. Negative control keeps it fixed at reference, optionally varying a nuisance parameter. A repeated reference is a computational null, not an independent laboratory control.</p><div class="grid two"><?php foreach(['reference'=>'Reference','candidate'=>'Candidate','negative'=>'Negative control','positive'=>'Positive control'] as $k=>$label):?><fieldset><legend><?=h($label)?></legend><?php foreach($m['params'] as $v):input('protocol[cases]['.$k.']['.$v['key'].']',$v['label'].' '.$v['unit'],$p['cases'][$k][$v['key']]??$v['default'],'number','step="any" min="'.h($v['min']).'" max="'.h($v['max']).'"');endforeach;?></fieldset><?php endforeach;?></div><div class="grid two"><?php foreach(['negative_control'=>'Why should the negative control have no effect?','positive_control'=>'Why should the positive control respond?'] as $k=>$label):?><label class="field"><span><?=h($label)?></span><textarea required name="protocol[notes][<?=$k?>]" rows="3" maxlength="1500"><?=h($p['notes'][$k])?></textarea></label><?php endforeach;?></div></section><section class="panel"><h2>3 · Prespecify decision rules</h2><p>Signed effect = predicted direction × (case − reference). All bounds use the selected observable's units. Numerical support threshold must exceed rejection threshold. Controls must pass before a candidate decision is reported.</p><div class="grid two"><?php foreach(['support'=>'Minimum signed effect for support','reject'=>'Maximum signed effect for rejection','negative_tolerance'=>'Maximum absolute negative-control effect','positive_minimum'=>'Minimum signed positive-control effect'] as $k=>$label):input('protocol[criteria]['.$k.']',$label,$p['criteria'][$k],'number','step="any" min="0" max="1000000000"');endforeach;?></div><h3>Conservative effect uncertainty budget</h3><p>Enter nonnegative absolute effect-error bounds. The sum U is applied to each signed effect as ±U. These are user assumptions, not standard errors, measured uncertainties or confidence intervals.</p><div class="grid three"><?php foreach(['numerical'=>'Numerical bound','calibration'=>'Calibration bound','other'=>'Other bound'] as $k=>$label):input('protocol[uncertainty]['.$k.']',$label,$p['uncertainty'][$k],'number','step="any" min="0" max="1000000000"');endforeach;?></div></section><section class="panel"><h2>4 · Link evidence and open gates</h2><p>Associations are editorial. A computational outcome does not close a validation gate.</p><details open><summary>Evidence records</summary><div class="checks"><?php foreach(\records() as $id=>$r):?><label><input type="checkbox" name="protocol[evidence][]" value="<?=h($id)?>" <?=in_array($id,$p['evidence'],true)?'checked':''?>> <a href="/evidence/ledger/<?=h($id)?>/"><?=h($r['title'])?></a></label><?php endforeach;?></div></details><details open><summary>Validation requirements</summary><div class="checks"><?php foreach(\corpus()['gates'] as $g):?><label><input type="checkbox" name="protocol[gates][]" value="<?=h($g['id'])?>" <?=in_array($g['id'],$p['gates'],true)?'checked':''?>> <?=h($g['id'].' — '.$g['title'])?></label><?php endforeach;?></div><a href="/evidence/gates/">Read all acceptance criteria →</a></details></section><div class="actions"><button type="submit">Seal protocol without executing</button></div></form><?php }
function home():void{$method=route(ROOT,['GET','HEAD','POST']);$preset=$_GET['preset']??'photon';$id=$_GET['model']??null;$p=is_string($preset)&&isset(presets()[$preset])?presets()[$preset]:presets()['photon'];if(is_string($id)&&isset(model_specs()[$id]))$p=custom($id);$sealed=null;$error='';if($method==='POST'){try{$p=from_form($_POST);$sealed=seal($p);}catch(\InvalidArgumentException|\JsonException $e){http_response_code(400);$error=$e->getMessage();}}start('Scientific Experiment Design Studio','Design a falsifiable four-case numerical investigation, seal decision criteria and inspect controls before interpreting the results.',ROOT,$method==='POST'||isset($_GET['preset'])||isset($_GET['model']));?><section class="intro"><span class="eyebrow">EXPERIMENT DESIGN · 2.3</span><h1>Decide the test <em>before</em> seeing the result.</h1><p class="lead">Design a controlled numerical study using the existing research models. Declare your question, predicted effect, controls and decision thresholds. Seal the protocol, then run it.</p><div class="actions"><a class="button secondary" href="/experiment-design/replay/">Import & replay</a><a class="button secondary" href="/experiment-design/method/">Methods and API</a></div></section><?php if($error):?><p class="notice error" role="alert"><?=h($error)?>. No cases executed. Use your browser’s Back action to recover the draft, or start again below. <a href="/experiment-design/">Return to the default template</a>.</p><?php endif;if($sealed):?><section class="panel"><h2>Sealed protocol — no study cases executed</h2><p><?=h($sealed['notice'])?></p><p class="hash"><?=h($sealed['seal_sha256'])?></p><form method="post" action="/experiment-design/replay/"><label class="field"><span>Save or inspect this exact sealed JSON</span><textarea id="sealed-json" name="sealed" readonly rows="12"><?=h(json_pretty($sealed))?></textarea></label><div class="actions"><button type="submit" name="action" value="run">Execute sealed protocol</button><button class="secondary" name="action" value="save" type="submit">Download sealed protocol</button></div></form><p><a href="/experiment-design/">Start a new draft</a></p></section><?php else:?><section class="panel"><h2>Choose a worked design</h2><div class="preset-grid"><?php foreach(presets() as $slug=>$v):?><a class="preset" href="/experiment-design/?preset=<?=h($slug)?>"><strong><?=h($v['title'])?></strong><small>Four controlled cases</small></a><?php endforeach;?></div><form method="get" action="/experiment-design/" class="actions"><label class="field"><span>Or create a custom design using any of the 15 models</span><select name="model"><?php foreach(model_specs() as $key=>$m):?><option value="<?=h($key)?>" <?=$key===($p['model']??'')?'selected':''?>><?=h($m['title'])?></option><?php endforeach;?></select></label><button type="submit" class="secondary">Load model</button></form></section><?php if(!$error)form($p);else if(isset($p['model'])&&is_string($p['model'])&&isset(model_specs()[$p['model']])){try{$safe=custom($p['model']);form($safe);}catch(\Throwable $e){}} endif;?><section class="notice"><h2>What this studio does not establish</h2><p>A content seal is not an independent timestamp. Model-generated values are not observations, uncertainty budgets are not confidence intervals, and meeting a numerical criterion does not validate an alternative cosmology.</p></section><?php endpage();}
function csv_result(array $r):never{header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="beyondspacetime-design-effects.csv"');$f=fopen('php://output','w');fputcsv($f,['role','value','delta','signed_effect','lower','upper'],',','"','');foreach($r['effects'] as $k=>$v)fputcsv($f,array_merge([$k],array_values($v)),',','"','');fclose($f);exit;}
function effect_chart(array $r):void{$c=$r['sealed']['protocol']['criteria'];$rows=$r['effects'];$lo=min(0,$c['reject'],...array_column($rows,'lower'));$hi=max($c['support'],$c['positive_minimum'],...array_column($rows,'upper'));if($hi<=$lo)$hi=$lo+1;$x=fn($v)=>120+($v-$lo)/($hi-$lo)*550;?><figure class="effect-figure"><svg viewBox="0 0 710 245" role="img" aria-label="Signed effects with declared absolute error bounds, in the same units as the primary observable"><rect x="<?=$x($c['reject'])?>" y="35" width="<?=$x($c['support'])-$x($c['reject'])?>" height="160" class="indeterminate"/><line x1="<?=$x($c['reject'])?>" x2="<?=$x($c['reject'])?>" y1="25" y2="205" class="reject-line"/><line x1="<?=$x($c['support'])?>" x2="<?=$x($c['support'])?>" y1="25" y2="205" class="support-line"/><?php foreach(['candidate','negative','positive'] as $i=>$k):$y=65+$i*50;$v=$rows[$k];?><text x="110" y="<?=$y+5?>" text-anchor="end"><?=h(ucfirst($k))?></text><line x1="<?=$x($v['lower'])?>" x2="<?=$x($v['upper'])?>" y1="<?=$y?>" y2="<?=$y?>" class="effect-line"/><circle cx="<?=$x($v['signed_effect'])?>" cy="<?=$y?>" r="5" class="effect-dot"/><?php endforeach;?><line x1="120" x2="670" y1="205" y2="205" class="axis"/><?php for($i=0;$i<=4;$i++):$v=$lo+($hi-$lo)*$i/4;?><text x="<?=$x($v)?>" y="225" text-anchor="middle"><?=h(fmt($v))?></text><?php endfor;?></svg><figcaption>Blue markers: signed effects; lines: ±U bounds. Gold dashed line: rejection threshold. Green dashed line: support threshold. Shading: between candidate thresholds; controls have their own acceptance criteria. The table provides exact numeric values.</figcaption></figure><?php }
function results(array $r,?bool $match=null):void{$p=$r['sealed']['protocol'];$c=$p['criteria'];$names=['criterion_met'=>'Numerical criterion met','criterion_not_met'=>'Numerical criterion not met','inconclusive'=>'Inconclusive numerical result','controls_not_met'=>'Controls not met — no candidate decision'];?><section class="panel result"><span class="eyebrow">SEALED STUDY RESULT</span><h2><?=h($names[$r['decision']])?></h2><p><?=h($r['interpretation'])?></p><h3><?=h($p['title'])?></h3><p>Primary observable: <?=h($r['observable']['label'].' '.$r['observable']['unit'])?> · Effect direction <?=h($p['direction'])?></p><div class="stats"><div><strong><?=h(fmt($r['effects']['candidate']['signed_effect']))?></strong><span>Candidate signed effect</span></div><div><strong><?=h(fmt($r['effect_budget']))?></strong><span>Declared absolute error bound U</span></div><div><strong><?=$r['controls']['negative_met']?'Met':'Not met'?></strong><span>Negative control</span></div><div><strong><?=$r['controls']['positive_met']?'Met':'Not met'?></strong><span>Positive control</span></div></div><div class="table-scroll"><table><caption>Endpoint values and signed effect intervals (not confidence intervals)</caption><thead><tr><th scope="col">Case</th><th scope="col">Value</th><th scope="col">Raw Δ</th><th scope="col">Signed Δ</th><th scope="col">Lower</th><th scope="col">Upper</th></tr></thead><tbody><?php foreach($r['effects'] as $k=>$v):?><tr><th scope="row"><?=h(ucfirst($k))?></th><?php foreach(['value','delta','signed_effect','lower','upper'] as $col):?><td><?=h(fmt($v[$col]))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php effect_chart($r);?><p>Support ≥ <?=h(fmt($c['support']))?>; reject ≤ <?=h(fmt($c['reject']))?>; negative-control |Δ| + U ≤ <?=h(fmt($c['negative_tolerance']))?>; positive-control lower bound ≥ <?=h(fmt($c['positive_minimum']))?>.</p><?php if($match!==null):?><p class="notice">Result fingerprint <?=$match?'matches':'does not match'?> the provided digest. Matching is not proof of authenticity.</p><?php endif;?><p>Result SHA-256: <span class="hash"><?=h($r['result_sha256'])?></span></p><form method="post" action="/experiment-design/replay/"><input type="hidden" name="sealed" value="<?=h(enc($r['sealed']))?>"><button name="action" value="download">Recompute & download full evidence JSON</button> <button class="secondary" name="action" value="csv">Recompute & download effect CSV</button></form><h3>Related evidence and validation</h3><div class="grid two"><?php foreach($r['research_result']['evidence'] as $e):?><article class="tile"><a href="/evidence/ledger/<?=h($e['id'])?>/"><?=h($e['title'])?></a><p><?=h($e['limitation'])?></p></article><?php endforeach;?></div><p>Declared gates: <?=h(implode(', ',$p['gates'])?:'None selected')?>. All remain open unless independently established. <a href="/evidence/gates/">Gate requirements →</a></p><details><summary>Sealed protocol and source fingerprints</summary><pre><?=h(json_pretty($r['sealed']))?></pre></details></section><?php }
function replay():void{$method=route(ROOT.'replay/',['GET','HEAD','POST']);$error='';$raw='';$r=null;$match=null;if($method==='POST'){try{$raw=$_POST['sealed']??'';$d=decode_text($raw);$expected=null;if(($d['schema']??'')==='beyondspacetime.design-result.v1'){$expected=$d['result_sha256']??null;$d=obj($d['sealed']??null,'Sealed protocol');}if($expected!==null&&(!is_string($expected)||!preg_match('/^[0-9a-f]{64}$/D',$expected)))throw new \InvalidArgumentException('Invalid result digest.');if(($_POST['action']??'')==='save'){$s=verified_seal($d);download($s,'beyondspacetime-sealed-protocol.json');}$r=run($d);$match=$expected===null?null:hash_equals($expected,$r['result_sha256']);if(($_POST['action']??'')==='csv')csv_result($r);if(($_POST['action']??'')==='download')download($r,'beyondspacetime-design-result.json');$raw=json_pretty($r['sealed']);}catch(\InvalidArgumentException|\JsonException $e){http_response_code(400);$error=$e->getMessage();}catch(\Throwable $e){http_response_code(500);error_log('BSP design: '.$e->getMessage());$error='Calculation failed.';}}start('Replay a sealed protocol','Recompute a previously sealed experiment design and verify its content fingerprint.',ROOT.'replay/',true);?><section class="intro"><span class="eyebrow">REPRODUCIBLE PROTOCOL</span><h1>Verify and replay.</h1><p>Paste a sealed protocol or select a saved JSON file. Imported numerical results are ignored; execution uses the validated recipe and current source fingerprints.</p></section><?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif;if($r)results($r,$match);?><form class="panel" method="post" action="/experiment-design/replay/"><label class="field"><span>Protocol or result JSON</span><textarea id="replay-json" name="sealed" rows="12" required maxlength="65536"><?=h(is_string($raw)&&strlen($raw)<=65536?$raw:'')?></textarea></label><label id="file-picker" hidden class="field"><span>Load JSON file (maximum 1 MiB; result exports are reduced to the sealed recipe)</span><input type="file" id="import-file" accept=".json,application/json"></label><p id="import-status" role="status"></p><div class="actions"><button name="action" value="run">Verify seal & execute</button><a class="button secondary" href="/experiment-design/">New protocol</a></div></form><?php endpage();}
function method_page():void{route(ROOT.'method/',['GET','HEAD']);start('Scientific experiment design methods','Protocol schema, decision rules, uncertainty budget and reproducibility API.',ROOT.'method/');?><section class="intro"><span class="eyebrow">SCIENTIFIC METHOD</span><h1>Design, seal, execute, interpret.</h1><p class="lead">A bounded computational study, not a laboratory experiment or an independently registered protocol.</p></section><section class="panel"><h2>Decision rules</h2><p>Let S be the candidate-minus-reference effect multiplied by +1 for an increase or −1 for a decrease. Let U be the sum of the three nonnegative absolute effect bounds. Negative control passes if |Δ| + U ≤ its tolerance. Positive control passes if its signed effect − U ≥ its minimum. Only if both pass: support if S − U ≥ support threshold; rejection if S + U ≤ rejection threshold; otherwise inconclusive. The rules are applied to unrounded values. All quantities refer to the same numeric observable and unit.</p><p>Candidate and positive cases hold non-primary parameters constant. The negative control holds the primary variable at reference. A computational control does not demonstrate detector calibration. The supplied numerical bounds are illustrative user-defined budgets, not statistical uncertainties.</p><h2>Programmatic use</h2><p><a href="/experiment-design/catalog.json">Static design catalog</a> · <a href="/experiment-design/api/">Live API catalog</a> · <a href="/experiment-design/openapi.json">OpenAPI description</a></p><p>POST application/json to /experiment-design/api/ using an action of seal or run. Seal normalizes the protocol and identifies the installed solver and PHP runtime. Run requires the sealed object and recomputes results; optional expected_sha256 compares the result digest. The protocol has no trusted timestamp. Changing the source or runtime requires resealing; retain original results and document the revision. Maximum request size 64 KiB.</p><pre><?=h(json_pretty(['action'=>'seal','protocol'=>presets()['photon']]))?></pre><p>Then submit <code>{"action":"run","sealed": ...}</code>. Existing <a href="/research/protocol/">research API / AG-UI subset</a> is still authoritative for arbitrary multi-case execution. This design API is plain JSON.</p><h2>Empirical follow-up</h2><p>Real experiments require apparatus, calibration, sampling, uncertainty analysis, exclusion rules and independent evidence. The study notes capture proposed plans but the software does not validate their scientific adequacy. Open validation gates remain open.</p></section><?php endpage();}
